import math

def solve():
    min_val = float('inf')
    best_pair = (0, 0)

    for x in range(1, 1000):
        for y in range(1, x + 1):
            val = x*x - 6*x*y + y*y
            if val >= 0:
                root = int(math.isqrt(val))
                if root * root == val:
                    if math.gcd(x, y) == 1:
                        current_val = (x*x + y*y) / (x*y)
                        if current_val < min_val:
                            min_val = current_val
                            best_pair = (x, y)
    return min_val, best_pair

print(solve())

